class Solution {
    public int compress(char[] chars) {
        int write = 0, read = 0;
        while (read < chars.length) {
            char ch = chars[read];
            int count = 0;
            while (read < chars.length && chars[read] == ch) {
                read++;
                count++;
            }
            chars[write++] = ch;
            if (count > 1) {
                String cnt = String.valueOf(count);
                for (char c : cnt.toCharArray()) {
                    chars[write++] = c;
                }
            }
        }
        return write;
    }
}

class Solution {
    public int compress(char[] chars) {
        int write = 0;
        int i = 0;
        while (i < chars.length) {
            char ch = chars[i];
            int start = i;
            while (i < chars.length && chars[i] == ch) i++;
            chars[write++] = ch;
            int count = i - start;
            if (count > 1) {
                int anchor = write;
                while (count > 0) {
                    chars[write++] = (char)('0' + count % 10);
                    count /= 10;
                }
                int left = anchor;
                int right = write - 1;
                while (left < right) {
                    char tmp = chars[left];
                    chars[left] = chars[right];
                    chars[right] = tmp;
                    left++;
                    right--;
                }
            }
        }
        return write;
    }
}
